CREATE TYPE transaction_mode_type AS ENUM('ATM', 'POS', 'E-COMM');
CREATE TABLE IF NOT EXISTS settlement_account_mapper ( id bigserial NOT NULL PRIMARY KEY, transaction_source_code smallint NOT NULL UNIQUE, description varchar(50) NOT NULL, transaction_mode transaction_mode_type, account_number varchar(20) NOT NULL, aml_check boolean NOT NULL DEFAULT TRUE, callback_url varchar(100), created_at timestamp without time zone NULL DEFAULT now(), last_updated_at timestamp without time zone NULL ); INSERT INTO settlement_account_mapper (transaction_source_code, description, transaction_mode, account_number, aml_check) VALUES (1, 'collection', 'POS', '245990053', TRUE);
INSERT INTO settlement_account_mapper (transaction_source_code, description, transaction_mode, account_number, aml_check) VALUES (2, 'refund', 'POS', '245990053', TRUE);
